('エリシテーション（引き出し）','Elicitation',C_SC,'ステークホルダーなどから、繰り返しの作業を通じて情報を引き出し集めること。','',['要求・要件（ビジネスアナリシス）'],['IIBA'],['エリシテーション']),
('ユーザーストーリー','User Story',C_SC,'特定のステークホルダーに価値を届ける機能や品質を、短く表した文。','',['ユースケース','プロダクトバックログ'],['IIBA'],[]),
('ステークホルダー分析','Stakeholder Analysis',C_ST,'変化の影響を受けうるステークホルダーを特定し、その影響・関与・ニーズを評価すること。','',['利害関係者'],['IIBA'],[]),
('制約','Constraint',C_RK,'ソリューションのあり方や、できることを限定する、動かせない要因。','',['前提'],['IIBA'],[]),
('マイルストーン','Milestone',C_SD,'期間を持たない、重要な出来事や達成を示す時点。資源は消費しない。','日付の入った締切の一覧と同じ意味ではない（出来事・達成を示す）。',['クリティカルパス'],['GAO16'],[]),
('アクティビティ','Activity',C_SD,'スケジュール上の最下位にある個別の作業。推定された期間と割り当てられた資源を持つ。','',['WBS（作業分解構成図）'],['GAO16'],[]),
('先行・後続の依存関係','Dependency (predecessor and successor)',C_SD,'先行する作業が開始または完了してはじめて、後続の作業が始められる、という作業どうしのつながり。','',['クリティカルパス'],['GAO16'],['依存関係']),
('トータルフロート','Total Float',C_SD,'ある作業が何日遅れても、プログラム全体の完了予定日に影響しない余裕の長さ。','',['クリティカルパス'],['GAO16'],['総余裕']),
('ニアクリティカルパス','Near-critical Path',C_SD,'トータルフロートがクリティカルパスに近く、わずかな遅れで新たなクリティカルパスになりうる経路。','',['クリティカルパス','トータルフロート'],['GAO16'],[]),
('統合マスタースケジュール（IMS）','Integrated Master Schedule (IMS)',C_SD,'発注者・請負者などすべての関係者の必要な作業を、開始から終了まで網羅するプログラムのスケジュール。','',['クリティカルパス'],['GAO16'],['IMS']),
('スケジュールリスク分析','Schedule Risk Analysis',C_SD,'クリティカルパス法のスケジュールにリスクの情報を載せて統計的にシミュレーションし、完了日への確信度、必要な予備、優先して扱うべきリスクを見積もる手法。','',['スケジュールコンティンジェンシー'],['GAO16'],[]),
('スケジュールコンティンジェンシー','Schedule Contingency',C_SD,'スケジュールリスク分析をもとに、目標とする確信度に達するために設ける時間の予備。','',['スケジュールリスク分析'],['GAO16'],['スケジュール予備']),
('LOE（定常的な支援作業）','Level of Effort (LOE)',C_SD,'成果が測りにくく、時間の経過と結びついた作業（管理や監督など）。クリティカルパス上に置かない。','',['クリティカルパス'],['GAO16'],['Level of Effort']),
('サマリータスク','Summary Task',C_SD,'下位のアクティビティから日程が決まる、まとめ用の項目。他の作業と直接つながない。','',['アクティビティ'],['GAO16'],[]),
('アーンド・バリュー・マネジメント（EVM）','Earned Value Management (EVM)',C_CO,'技術的な範囲・スケジュール・コストを統合し、達成した作業の価値を、計画と実績のコストと比べて進捗を測る管理手法。','日本語では「出来高管理」とも呼ばれる（デジタル庁の資料）。指標だけを算出して終わりにしない。',['差異（バリアンス）'],['GAO20','DS120'],['EVM','出来高管理']),
('差異（バリアンス）','Variance',C_CO,'計画と実績の差。コストの差異とスケジュールの差異がある。','',['アーンド・バリュー・マネジメント（EVM）'],['GAO20'],['バリアンス']),
('コンティンジェンシー（予備費）','Contingency',C_RK,'発注者側のプログラム管理が保有する、請負者の管理が及ばない「未知の未知」に備える資金。','',['マネジメントリザーブ'],['GAO20'],['コンティンジェンシー']),
('マネジメントリザーブ','Management Reserve',C_RK,'契約の範囲に関わる「既知の未知」に備えて、請負者が管理する資金。','',['コンティンジェンシー（予備費）'],['GAO20'],[]),
('感度分析','Sensitivity Analysis',C_RK,'主要な前提・パラメータ・入力データを変化させて、コストなどの結果がどの範囲で変わるかを調べる手法。','',['前提条件と基本ルール'],['GAO20'],[]),
('前提条件と基本ルール','Ground Rules and Assumptions',C_RK,'見積りの境界を定める共通の基準と、条件についての判断。情報が限られる箇所では、前提と除外事項を文書にする。','',['感度分析','前提'],['GAO20'],[]),
('RFI（資料提供依頼）','Request for Information (RFI)',C_PR,'事業者に情報の提供を求めること。','',['RFP（提案依頼）'],['DS130','DS120'],['RFI']),
('意見招請','Request for Comments on Specifications',C_PR,'入札公告の前に、仕様書案について事業者から意見を求めること（官公庁の調達用語）。','',['RFI（資料提供依頼）'],['DS130'],[]),
('ベンダー','Vendor',C_PR,'販売会社や情報システムの開発会社。','',['ベンダーロックイン'],['DS130'],[]),
('ベンダーロックイン','Vendor Lock-in',C_PR,'特定のベンダーの製品やシステムに囲い込まれ、他社の参入や乗り換えが難しくなった状態。','',['ベンダー'],['DS130'],[]),
('準委任契約','Quasi-mandate Contract',C_PR,'専門家としての注意義務を果たす業務に対して対価を支払う契約。アジャイル開発になじみやすいとされる（デジタル庁の資料）。','契約の適否や法的な効果は、個別の事案ごとに専門家へ確認する。',['請負契約'],['DS121'],[]),
('請負契約','Contract for Work',C_PR,'成果物の完成に対して対価を支払う契約。','契約の適否や法的な効果は、個別の事案ごとに専門家へ確認する。',['準委任契約'],['DS121'],[]),
('PJMO（プロジェクト推進組織）','Project Management Office (PJMO)',C_GV,'デジタル庁の標準ガイドライン群で、個々のプロジェクトを遂行し、進捗を管理する組織を指す呼び名。','政府の標準ガイドラインでは、PMO（府省内全体の管理）とPJMO（個別プロジェクトの推進）を区別している。民間では呼び方が異なることがある。',['プロジェクトマネジメントオフィス'],['DS130','DS120'],['PJMO']),
('原理・原則（PMBOK第7版）', 'Principles (PMBOK Guide 7th)', 'PMBOKガイド第7版', 'PMBOKガイド第7版が示す12の行動の指針。スチュワードであること、協働的なチーム環境の構築、ステークホルダーとの効果的な関与、価値への焦点、システムの相互作用への対応、リーダーシップ、状況に基づくテーラリング、品質の組み込み、複雑さへの対処、リスク対応の最適化、適応力と回復力、変革の実現、の12項目。', '規範（やり方の決まり）ではなく、振る舞いの指針として示されている。', ['パフォーマンス領域（PMBOK第7版）', 'テーラリング'], ['PMIJ_SZ'], []),
('パフォーマンス領域（PMBOK第7版）', 'Performance Domains (PMBOK Guide 7th)', 'PMBOKガイド第7版', 'PMBOKガイド第7版が示す8つの領域。ステークホルダー、チーム、開発アプローチとライフサイクル、計画、プロジェクト作業、デリバリー、測定、不確かさ。互いに依存する統合システムで、決まった重みや順序はない。', '領域を順番に実施するという意味ではない。', ['原理・原則（PMBOK第7版）'], ['PMIJ_SZ'], ['パフォーマンス・ドメイン']),
('テーラリング', 'Tailoring', 'PMBOKガイド第7版', 'アプローチ、ガバナンス、プロセスが、特定の環境および目前の作業により適合するように、それらを慎重に適応させること。', '手順を省くことと同じではない。環境に合わせて意図して調整する行為。', ['開発アプローチ', '原理・原則（PMBOK第7版）'], ['PMIJ_UPD', 'PMIJ_SZ'], []),
('開発アプローチ', 'Development Approach', 'PMBOKガイド第7版', 'プロジェクトのライフサイクル中にプロダクト、サービス、または所産を創出して発展させるために使用される手法。予測型、反復型、漸進型、アジャイル型、またはハイブリッドの手法など。', '', ['適応型アプローチ', '漸進型アプローチ', 'テーラリング'], ['PMIJ_UPD'], []),
('適応型アプローチ', 'Adaptive Approach', 'PMBOKガイド第7版', '要求事項の不確かさと変動性の度合いが高く、プロジェクト全体にわたって要求事項が変わり得る開発アプローチ。', '', ['開発アプローチ', '漸進型アプローチ'], ['PMIJ_UPD'], ['適応型開発アプローチ']),
('漸進型アプローチ', 'Incremental Approach', 'PMBOKガイド第7版', '適応型開発アプローチの一つ。完了と見なされる必要十分な能力が含まれるまで成果物の作成を続け、機能を追加する。', '', ['適応型アプローチ', 'インクリメント'], ['PMIJ_UPD'], ['漸進型開発アプローチ']),
('アジャイル（PMBOK第7版）', 'Agile (PMBOK Guide 7th)', 'PMBOKガイド第7版', 'アジャイル宣言で表明されている価値と原則のマインドセットを説明するために使用される用語。', '特定の手順や道具の名前ではなく、考え方を指す用語として定義されている。', ['アジャイルソフトウェア開発宣言', 'アジャイル型開発'], ['PMIJ_UPD'], []),
('価値実現オフィス（VDO）', 'Value Delivery Office (VDO)', 'PMBOKガイド第7版', 'チームのコーチング、組織全体でのアジャイル・スキルと能力の構築、スポンサーやプロダクト・オーナーが効果的に役割を果たせるようにするための指導などに重点を置いた、プロジェクトの実施を支援する組織。', '', [], ['PMIJ_UPD'], ['VDO', 'Value Delivery Office']),
('顧客の声（VOC）', 'Voice of the Customer (VOC)', 'PMBOKガイド第7版', 'プロダクト、サービス、所産を提供するために用いられる計画方法の一つ。プロジェクトやプロダクト開発のフェーズごとに、顧客の要望を適切な技術的要求事項に変換して顧客の要望を正確に反映する。', '', [], ['PMIJ_UPD'], ['VOC', 'Voice of the Customer']),
('プロジェクト・ビジョン記述書', 'Project Vision Statement', 'PMBOKガイド第7版', 'プロジェクトの目的が明示された、プロジェクトの簡潔で概要的な説明。チームのプロジェクトへの貢献を動機付ける。', '', [], ['PMIJ_UPD'], []),
('品質方針', 'Quality Policy', 'PMBOKガイド第7版', '組織が品質マネジメントに組織のシステムを組み入れる際に、組織行動のガバナンスを実行する基本原則。', '', [], ['PMIJ_UPD'], []),
('リスク報告書', 'Risk Report', 'PMBOKガイド第7版', 'プロジェクト文書の一つ。プロジェクトの個別リスクに関する情報と全体リスクのレベルに関する情報とをまとめたもの。', '', [], ['PMIJ_UPD'], []),
('ログ（プロジェクト）', 'Log', 'PMBOKガイド第7版', 'プロセスや活動の実行中に取り上げると決めた項目を記録し、記述し、明示するために用いる文書。通常は、課題、変更、あるいは前提条件などの語を前に付けて使用される。', '', [], ['PMIJ_UPD'], ['課題ログ', '変更ログ']),
